import { ValidationException, ValueObject } from '@core/domain';

/***

 @deprecated No usar
 **/
export class ProductId extends ValueObject<number> {
  private constructor(value: number) {
    super(value);
  }

  static from(id: number): ProductId {
    if (!this.isValid(id)) {
      throw new ValidationException('id', id, 'Product ID must be a positive number');
    }
    return new ProductId(id);
  }

  static generate(): ProductId {
    // In a real scenario, this might be generated by the backend
    return new ProductId(Math.floor(Math.random() * 1000000));
  }

  private static isValid(id: number): boolean {
    return Number.isInteger(id) && id > 0;
  }
}
